Algorithme EcritureEtLectureFichier;
Var
    f : Fichier de Entier;
    n, val : Entier;
Debut
    // 1. ÉCRITURE DE 5 NOMBRES DANS LE FICHIER
    f := Ouvrir("scores.dat", "Écriture");
    Pour n := 1 a 5 Faire
        Ecrire(f, n * 10);
    Fin Pour;
    Fermer(f); // Validation physique sur le disque

    // 2. LECTURE SÉQUENTIELLE DU FICHIER
    f := Ouvrir("scores.dat", "Lecture");
    TantQue (Non(FinFichier(f))) Faire
        Lire(f, val);
        Ecrire("Valeur lue sur disque : ", val);
    Fin TantQue;
    Fermer(f);
Fin.
